    # This catches sha256→sha1 mutation and pbkdf2_hmac('md5', ...) patterns
    if hashlib.weak_algorithm_used:
        assert False, \
            f"Weak crypto: {hashlib.last_algorithm} used. Use SHA-256, bcrypt, or stronger."

