    import inspect
    sig = None
    try:
        sig = inspect.signature(handle_form_v4)
        first_param = list(sig.parameters.values())[0] if sig.parameters else None
        if first_param and first_param.annotation == dict:
            request = dict_request
        else:
            request = MockRequest()
    except Exception:
        request = MockRequest()

    # C10 fix: Use signature-aware call with request as payload
    request_rejected = False
    try:
        params = list(sig.parameters.keys()) if sig and sig.parameters else []
        if len(params) == 1:
            result = handle_form_v4(request)
        elif len(params) >= 2:
            # Multi-param: pass request + fill remaining with defaults
            kwargs = {params[0]: request}
            for p in params[1:]:
                if sig and p in sig.parameters and sig.parameters[p].default is not inspect.Parameter.empty:
