import hashlib
import os
import pytest

def hash_master_secret(master_pw):
    """Hash master secret using PBKDF2 with SHA-256."""
    vault_salt = os.urandom(32)
    stretched = hashlib.pbkdf2_hmac('sha256', master_pw.encode(), vault_salt, 100000)
    return vault_salt.hex() + ':' + stretched.hex()

def test_hash_master_secret_basic():
    assert hash_master_secret("password123") == f"{os.urandom(32).hex()}:{hashlib.pbkdf2_hmac('sha256', b'password123', os.urandom(32), 100000).hex()}"

def test_hash_master_secret_empty_password():
    assert hash_master_secret("") == f"{os.urandom(32).hex()}:{hashlib.pbkdf2_hmac('sha256', b'', os.urandom(32), 100000).hex()}"

def test_hash_master_secret_special_characters():
    assert hash_master_secret("!@#$%^&*()") == f"{os.urandom(32).hex()}:{hashlib.pbkdf2_hmac('sha256', b'!@#$%^&*()', os.urandom(32), 100000).hex()}"

def test_hash_master_secret_long_password():
    long_password = "a" * 100
    assert len(hash_master_secret(long_password)) > 0

def test_hash_master_secret_short_password():
    short_password = "a"
    assert len(hash_master_secret(short_password)) > 0

