    password = "password"
    assert hash_master_secret(password) == hash_master_secret(password)

def test_hash_master_secret_different_salts():
    password = "password"
    salt1 = hash_master_secret(password)[:64]
    salt2 = hash_master_secret(password)[:64]
    assert salt1 != salt2
