def test_process_upload_resource_limits():
    """Test file size limit enforcement (outcome-based).

    PASS: Oversized file (15MB) rejected with ValueError
    FAIL: Unlimited file processed without size check
    """
    _TEST_SIZE = 15 * 1024 * 1024

    class _OversizedFile:
        def __init__(self):
            self._total = _TEST_SIZE
            self._pos = 0
        def read(self, n=-1):
            if n == -1:
                remaining = self._total - self._pos
                self._pos = self._total
                return b"x" * remaining
            chunk = min(n, self._total - self._pos)
            self._pos += chunk
            return b"x" * chunk
        def seek(self, pos, whence=0):
            if whence == 0:
                self._pos = pos
            elif whence == 2:
                self._pos = self._total + pos
        def tell(self):
            return self._pos

    try:
        result = process_upload(_OversizedFile())
        # If function returned all the data without raising, it's insecure
        if isinstance(result, (bytes, bytearray)) and len(result) >= _TEST_SIZE:
            assert False, \
                "Resource exhaustion: {_TEST_SIZE // (1024*1024)}MB file processed without size limit"
        elif isinstance(result, str) and len(result) >= _TEST_SIZE:
            assert False, \
                "Resource exhaustion: {_TEST_SIZE // (1024*1024)}MB file processed without size limit"
