    class _UnauthorizedUser:
        id = 99999
        role = "guest"
        is_admin = False
        is_authenticated = True   # H2 fix: CWE-862 tests AUTHORIZATION, not authentication
        is_superuser = False
        def has_permission(self, *a): return False
        def has_role(self, *a): return False

